\set ON_ERROR_STOP on
SELECT 'households' AS entity,count(*) FROM households UNION ALL SELECT 'accounts',count(*) FROM accounts UNION ALL SELECT 'categories',count(*) FROM categories UNION ALL SELECT 'transactions',count(*) FROM transactions UNION ALL SELECT 'entries',count(*) FROM entries UNION ALL SELECT 'splits',count(*) FROM splits UNION ALL SELECT 'allocations',count(*) FROM allocations UNION ALL SELECT 'batches',count(*) FROM batches UNION ALL SELECT 'import_rows',count(*) FROM import_rows UNION ALL SELECT 'audit',count(*) FROM audit;
SELECT a.household_id,a.id,a.name,a.opening_balance+COALESCE(sum(e.amount) FILTER(WHERE NOT t.voided),0) AS derived_balance FROM accounts a LEFT JOIN entries e ON e.account_id=a.id LEFT JOIN transactions t ON t.id=e.transaction_id GROUP BY a.household_id,a.id ORDER BY a.household_id,a.id;
SELECT c.household_id,c.id,c.name,COALESCE(sum(s.amount * CASE WHEN t.kind='expense' THEN 1 ELSE -1 END) FILTER(WHERE NOT t.voided),0) AS net_spending FROM categories c LEFT JOIN splits s ON s.category_id=c.id LEFT JOIN transactions t ON t.id=s.transaction_id GROUP BY c.household_id,c.id ORDER BY c.household_id,c.id;
SELECT household_id,category_id,month,sum(amount) AS assigned FROM allocations GROUP BY household_id,category_id,month ORDER BY household_id,category_id,month;
SELECT household_id,category_id,year,amount AS target FROM targets ORDER BY household_id,category_id,year;
